def visit(self, node, *args, **kwargs):
    node_type = node['type']
    method = self._method_cache.get(node_type)
    if method is None:
        method = getattr(
            self, 'visit_%s' % node['type'], self.default_visit)
        self._method_cache[node_type] = method
    return method(node, *args, **kwargs)
